int arr[5] = {10, 20, 30, 40, 50};
int *p = arr + 2; // p points to arr[2], value 30
p++; // now p points to arr[3], value 40
int value = *(p + 1); // access arr[4], value 50
p += 2; // p now points beyond arr[4], undefined behavior if dereferenced
// Demonstrates advanced pointer arithmetic with array traversal
